<?php require 'app/init.php';$u=require_user();if($_SERVER['REQUEST_METHOD']!=='POST')go();verify();$id=filter_var($_POST['id']??null,FILTER_VALIDATE_INT);if(!$id)go();$accion=$_POST['accion']??'';if($accion==='like'||$accion==='guardar'){$table=$accion==='like'?'reacciones':'guardados';$s=db()->prepare("SELECT 1 FROM $table WHERE usuario_id=? AND publicacion_id=?");$s->execute([$u['id'],$id]);if($s->fetch()){$s=db()->prepare("DELETE FROM $table WHERE usuario_id=? AND publicacion_id=?");}else{$s=db()->prepare("INSERT IGNORE INTO $table(usuario_id,publicacion_id) VALUES(?,?)");}$s->execute([$u['id'],$id]);}elseif($accion==='comentar'){$body=trim($_POST['contenido']??'');if($body&&mb_strlen($body)<=2000){$s=db()->prepare('INSERT INTO comentarios(publicacion_id,usuario_id,contenido) VALUES(?,?,?)');$s->execute([$id,$u['id'],$body]);}}go('publicacion.php?id='.$id);